ard[data-size=\"6x3\"] .sub .sep{display:none}\n.card[data-size=\"6x3\"] .tabs{flex-direction:column;gap:2px}\n.card[data-size=\"6x3\"] .tab{height:23px;justify-content:space-between;padding:0 8px}\n.card[data-size=\"6x3\"] .add{align-self:end;width:100%;height:28px;border-radius:10px}\n\n.card[data-size=\"6x6\"] .board{padding:10px;gap:8px;grid-template-columns:repeat(3,minmax(0,1fr));grid-template-rows:auto auto minmax(0,1fr);\n  grid-template-areas:\"head head add\" \"bar bar bar\" \"c0 c1 c2\";}\n.card[data-size=\"6x6\"] .ttl{font-size:16px}\n.card[data-size=\"6x6\"] .sub{font-size:11px}\n.card[data-size=\"6x6\"] .add{justify-self:end;height:30px;padding:0 14px}\n.col{min-width:0;min-height:0;display:flex;flex-direction:column;background:var(--soft);border-radius:10px;padding:5px;gap:5px}\n.c0{grid-area:c0}.c1{grid-area:c1}.c2{grid-area:c2}\n.col-h{flex:none;display:flex;align-items:center;justify-content:space-between;padding:0 3px;font-size:12px;color:var(--ink)}\n.col-h .tn{min-width:18px;padding:0 5px;border-radius:9px;background:var(--accent);color:var(--on-accent);font-size:10.5px;font-weight:700;text-align:center;line-height:18px}\n.col-b{flex:1 1 auto;min-height:0;min-width:0;overflow-y:auto;display:flex;flex-direction:column;gap:4px}\n.card[data-size=\"6x6\"] .t-title{-webkit-line-clamp:3}\n.card[data-size=\"6x6\"] .t-foot{flex-wrap:wrap}\n.card[data-size=\"6x6\"] .t-meta{flex:1 1 100%;flex-wrap:wrap}\n.card[data-size=\"6x6\"] .t-acts{margin-left:auto}\n.card[data-size=\"6x6\"] .empty{padding:10px 4px}\n";
function stName(k){return k==='doing'?'进行中':k==='done'?'已完成':'待做';}
function pDay(s){var p=String(s).split('-').map(Number);return new Date(p[0],(p[1]||1)-1,p[2]||1);}
function dayDiff(a,b){return Math.round((pDay(a)-pDay(b))/86400000);}
function fmtMD(d){return (d.getMonth()+1)+'/'+d.getDate();}
function wkName(i){return '日一二三四五六'.charAt(i);}
function weekInfo(today){
  var d=pDay(today),off=(d.getDay()+6)%7;
  var a=new Date(d.getFullYear(),d.getMonth(),d.getDate()-off);
  var b=new Date(a.getFullYear(),a.getMonth(),a.getDate()+6);
  return {start:a,end:b};
}
function dueInfo(t,today,wk){
  if(!t.due)return null;
  var pd=pDay(t.due),d=dayDiff(t.due,today);
  var w=Math.round((pd-wk.start)/86400000);
  var label=(w>=0&&w<=6)?'周'+wkName(pd.getDay()):fmtMD(pd);
  if(t.status==='done')return {text:label,cls:''};
  if(d<0)return {text:'逾期'+(-d)+'天',cls:'late'};
  if(d===0)return {text:'今天到期',cls:'soon'};
  if(d===1)return {text:'明天到期',cls:'soon'};
  return {text:label+'到期',cls:''};
}
function listMove(list,id,st){
  var t=list.find(function(x){return x.id===id;});
  if(!t||t.status===st)return list;
  return list.filter(function(x){return x.id!==id;}).concat([Object.assign({},t,{status:st})]);
}
function listPin(list,id){
  var t=list.find(function(x){return x.id===id;});
  if(!t)return list;
  var rest=list.filter(function(x){return x.id!==id;});
  var k=rest.findIndex(function(x){return x.status===t.status;});
  if(k<0)k=rest.length;
  rest.splice(k,0,t);
  return rest;
}
function listShift(list,id,dir){
  var i=list.findIndex(function(x){return x.id===id;});
  if(i<0)return list;
  var st=list[i].status,j=i+dir;
  while(j>=0&&j<list.length&&list[j].status!==st)j+=dir;
  if(j<0||j>=list.length)return list;
  var out=list.slice(),tmp=out[i];
  out[i]=out[j];out[j]=tmp;
  return out;
}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day,percent,size,editor,panel}=ctx;
  const tasks=(state&&state.tasks)||[];
  const today=day();
  const wk=weekInfo(today);
  const SH=['todo','doing','done'];
  const tab=SH.indexOf(ui.tab)>=0?ui.tab:'todo';
  const kanban=size==='6x6';

  function go(patch){Object.assign(ui,patch);redraw();}
  function nextUi(t){return {tab:t||tab,view:null,detailId:null,editId:null,draft:null,confirmDel:null};}
  function back(){go(nextUi());}
  function act(fn,nu){const p=nu?commit(fn,nu):update(fn);return p.catch(function(){return false;});}
  function moveTo(id,st,nu){return act(function(s){return {...s,tasks:listMove(s.tasks||[],id,st)};},nu);}
  function pin(id,nu){return act(function(s){return {...s,tasks:listPin(s.tasks||[],id)};},nu);}
  function shift(id,dir,nu){return act(function(s){return {...s,tasks:listShift(s.tasks||[],id,dir)};},nu);}
  function colOf(st){return tasks.filter(function(t){return t.status===st;});}
  function kids(a){return a.filter(Boolean);}

  function iconBtn(g,label,fn){
    return el('button',{class:'ib',type:'button','aria-label':label,title:label,onclick:function(e){e.stopPropagation();fn();}},g);
  }
  function openDetail(id){go({view:'detail',detailId:id,confirmDel:null});}

  function row(t,i){
    const di=dueInfo(t,today,wk),si=SH.indexOf(t.status),acts=[];
    if(i>0)acts.push(iconBtn('↑','置顶',function(){pin(t.id);}));
    if(kanban){
      if(si>0)acts.push(iconBtn('←','移到'+stName(SH[si-1]),function(){moveTo(t.id,SH[si-1]);}));
      if(si<2)acts.push(iconBtn('→','移到'+stName(SH[si+1]),function(){moveTo(t.id,SH[si+1]);}));
    }else if(si===0)acts.push(iconBtn('→','开始，移到进行中',function(){moveTo(t.id,'doing');}));
    else if(si===1)acts.push(iconBtn('✓','完成，移到已完成',function(){moveTo(t.id,'done');}));
    else acts.push(iconBtn('↩','重新打开，移到进行中',function(){moveTo(t.id,'doing');}));
    return el('div',{class:'task '+t.status,role:'button',tabindex:'0',title:t.title,
        onclick:function(){openDetail(t.id);},
        onkeydown:function(e){if(e.key==='Enter')openDetail(t.id);}},
      el('div',{class:'t-title'},t.title),
      el('div',{class:'t-foot'},
        el('div',{class:'t-meta'},...kids([
          t.project?el('span',{class:'prj',title:t.project},t.project):null,
          di?el('span',{class:'due '+di.cls},di.text):null])),
        el('div',{class:'t-acts'},...acts)));
  }

  function info(k,v){return el('div',{class:'info'},el('span',{class:'k'},k),el('span',{class:'v'},v));}

  function detail(){
    const t=tasks.find(function(x){return x.id===ui.detailId;});
    if(!t)return null;
    const col=colOf(t.status),ci=col.findIndex(function(x){return x.id===t.id;});
    const si=SH.indexOf(t.status),di=dueInfo(t,today,wk);
    const body=el('div',{class:'dt'},
      el('div',{class:'dt-title'},t.title),
      info('状态',stName(t.status)),
      info('项目',t.project||'未设置'),
      info('截止',t.due?t.due+(di?'（'+di.text+'）':''):'未设置'),
      info('顺序','第 '+(ci+1)+' / '+col.length+' 个'));
    let actions=[];
    if(ui.confirmDel===t.id){
      body.append(el('div',{class:'warn'},'确定删除这个任务吗？删除后无法恢复。'));
      actions=[
        {label:'确认删除',primary:true,onClick:function(){act(function(s){return {...s,tasks:(s.tasks||[]).filter(function(x){return x.id!==t.id;})};},nextUi(t.status));}},
        {label:'取消',onClick:function(){go({confirmDel:null});}}];
    }else{
      SH.forEach(function(k){
        if(k===t.status)return;
        actions.push({label:'移到「'+stName(k)+'」',primary:si<2&&k===SH[si+1],onClick:function(){moveTo(t.id,k,nextUi(k));}});
      });
      if(ci>0){
        actions.push({label:'置顶（排到最前）',onClick:function(){pin(t.id,nextUi(t.status));}});
        actions.push({label:'前移一位',onClick:function(){shift(t.id,-1,nextUi(t.status));}});
      }
      if(ci<col.length-1)actions.push({label:'后移一位',onClick:function(){shift(t.id,1,nextUi(t.status));}});
      actions.push({label:'编辑',onClick:function(){go({view:'edit',editId:t.id,draft:null});}});
      actions.push({label:'删除',onClick:function(){go({confirmDel:t.id});}});
    }
    return panel({title:'任务详情',body:body,actions:actions,onBack:back});
  }


  function saveTask(v){
    const title=String(v.title||'').trim();
    if(!title)return '请填写任务名称';
    const rec={title:title,project:String(v.project||'').trim(),due:String(v.due||''),status:SH.indexOf(v.status)>=0?v.status:'todo'};
    const editId=ui.editId,newId=uid();
    return commit(function(s){
      const list=s.tasks||[];
      if(editId){
        const old=list.find(function(t){return t.id===editId;});
        if(!old)return s;
        const nt=Object.assign({},old,rec);
        if(old.status!==rec.status)return {...s,tasks:list.filter(function(t){return t.id!==editId;}).concat([nt])};
        return {...s,tasks:list.map(function(t){return t.id===editId?nt:t;})};
      }
      return {...s,tasks:list.concat([Object.assign({id:newId,createdAt:today},rec)])};
    },nextUi(rec.status));
  }

  function editView(){
    const t=ui.editId?tasks.find(function(x){return x.id===ui.editId;}):null;
    if(!ui.draft)ui.draft=t?{title:t.title,project:t.project||'',due:t.due||'',status:t.status}:{title:'',project:'',due:'',status:tab};
    return editor({
      title:t?'编辑任务':'添加任务',
      draft:ui.draft,
      fields:[
        {key:'title',label:'任务',required:true,placeholder:'要做什么'},
        {key:'project',label:'所属项目',placeholder:'例如：官网改版'},
        {key:'due',label:'截止日期',type:'date'},
        {key:'status',label:'状态',type:'select',options:[{value:'todo',label:'待做'},{value:'doing',label:'进行中'},{value:'done',label:'已完成'}]}],
      onSave:saveTask,
      onBack:back,
      submitLabel:t?'保存':'添加'
    });
  }

  function emptyText(st){
    if(!tasks.length)return '还没有任务，点右上「+ 添加」开始';
    return st==='todo'?'没有待做的任务':st==='doing'?'没有进行中的任务':'还没有完成的任务';
  }

  function main(){
    const total=tasks.length,done=colOf('done').length;
    const pct=total?percent(done,total):0;
    const head=el('div',{class:'head'},
      el('div',{class:'ttl'},'本周任务'),
      el('div',{class:'sub'},
        el('span',{class:'wk'},fmtMD(wk.start)+'–'+fmtMD(wk.end)),
        el('span',{class:'sep'},' · '),
        el('span',{class:'cnt'},total?done+'/'+total+' 完成':'暂无任务')));
    const add=el('button',{class:'add',type:'button',onclick:function(){go({view:'edit',editId:null,draft:null});}},'+ 添加');
    const bar=el('div',{class:'bar'},el('i',{style:'width:'+pct+'%'}));
    let parts;
    if(kanban){
      parts=SH.map(function(k,ci){
        const col=colOf(k);
        return el('div',{class:'col c'+ci},
          el('div',{class:'col-h'},el('b',{},stName(k)),el('span',{class:'tn'},String(col.length))),
          el('div',{class:'col-b'},...(col.length?col.map(row):[el('div',{class:'empty'},tasks.length?'空':'暂无')])));
      });
    }else{
      const tabs=el('div',{class:'tabs',role:'tablist'},...SH.map(function(k){
        return el('button',{class:'tab'+(k===tab?' on':''),type:'button',role:'tab',onclick:function(){go({tab:k});}},
          el('span',{class:'tl'},stName(k)),el('span',{class:'tn'},String(colOf(k).length)));
      }));
      const col=colOf(tab);
      const list=el('div',{class:'list'},...(col.length?col.map(row):[el('div',{class:'empty'},emptyText(tab))]));
      parts=[tabs,list];
    }
    return el('div',{class:'board'},head,add,bar,...parts);
  }

  function sheet(n){return el('div',{class:'sheet'},n);}
  let content=null;
  if(ui.view==='edit')content=sheet(editView());
  else if(ui.view==='detail'){const d=detail();if(d)content=sheet(d);}
  root.append(content||main());
}

